namespace ghidra.app.plugin.core.symboltree.nodes;





using generic.theme;
using ghidra.app.util;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.model.symbol;
using resources;

public class CodeSymbolNode : SymbolNode {
	static readonly DataFlavor LOCAL_DATA_FLAVOR =
		new SymbolTreeDataFlavor("Symbol Tree Data Flavor - Local Labels");
	static readonly DataFlavor GLOBAL_DATA_FLAVOR =
		new SymbolTreeDataFlavor("Symbol Tree Data Flavor - Global Labels");
	static readonly DataFlavor EXTERNAL_DATA_FLAVOR =
		new SymbolTreeDataFlavor("Symbol Tree Data Flavor - External Data");

	//@formatter:off
	private static readonly Icon CODE_ICON = new GIcon("icon.plugin.symboltree.node.code");
	private static readonly Icon PINNED_ICON = new GIcon("icon.plugin.symboltree.node.code.pinned");
	private static readonly Icon EXTERNAL_ICON = new GIcon("icon.plugin.symboltree.node.code.external");
	private static readonly Icon DISABLED_CODE_ICON = ResourceManager.getDisabledIcon(CODE_ICON);
	private static readonly Icon DISABLED_EXTERNAL_ICON = ResourceManager.getDisabledIcon(EXTERNAL_ICON);
	//@formatter:on

	private string tooltip;

	private bool isExternal;

	public CodeSymbolNode(Program program, Symbol symbol) : base(program, symbol)
    {
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		if (isCut()) {
			return isExternal ? DISABLED_EXTERNAL_ICON : DISABLED_CODE_ICON;
		}
		if (isExternal) {
			return EXTERNAL_ICON;
		}
		return symbol.isPinned() ? PINNED_ICON : CODE_ICON;
	}

	/* @Override */
	public string getToolTip() {
		if (tooltip == null) {
			createTooltip();
		}
		return tooltip;
	}

	private void createTooltip() {
		if (symbol.isExternal()) {
			isExternal = true;
			tooltip = "External Symbol - " + symbol.getName(true);
			object @object = symbol.getObject();
			// Object might be null, so make sure we have an external location before adjusting tool tip.
			if (@object is ExternalLocation) {
				tooltip = ToolTipUtils.getToolTipText((ExternalLocation) @object, true);
			}
		}
		else if (symbol.isGlobal()) {
			tooltip = "Global Symbol - " + symbol.getName(true);
		}
		else {
			tooltip = "Local Symbol - " + symbol.getName(true);
		}
	}

	/* @Override */
	public DataFlavor getNodeDataFlavor() {
		if (isExternal) {
			return EXTERNAL_DATA_FLAVOR;
		}
		return symbol.isGlobal() ? GLOBAL_DATA_FLAVOR : LOCAL_DATA_FLAVOR;
	}

	/* @Override */
	public bool canCut() {
		return !symbol.isExternal();
	}

	/* @Override */
	public bool isLeaf() {
		return true;
	}
}
